def upgrade() -> None:
    # Faqat bo'sh ma'lumotlarni to'ldiramiz — admin /shelf orqali yozganlari o'zgarmaydi
    for title, description in DESCRIPTIONS:
        op.execute(
            journals.update()
            .where(journals.c.title == title, journals.c.description.is_(None))
            .values(description=description)
        )


def downgrade() -> None:
    # Faqat shu migratsiya yozgan (keyin o'zgartirilmagan) ma'lumotlarni tozalaymiz
    for title, description in DESCRIPTIONS:
        op.execute(
            journals.update()
            .where(journals.c.title == title, journals.c.description == description)
            .values(description=None)
        )
